<template>
  <section class="ds-overview-panel attention-panel">
    <header><div><h2>需要关注 <span class="count">{{ attentionProjects.length + problemNodes.length }}</span></h2><p>先定位失败项目和异常节点，再进入明细查看原因。</p></div><button class="link-button" @click="$emit('alerts')">查看项目告警 →</button></header>
    <div class="attention-items">
      <button v-for="p in attentionProjects.slice(0, 3)" :key="p.id" class="attention-item" :disabled="pending" @click="$emit('instances', p, 'FAILURE')"><span class="status down">执行失败</span><strong>{{ label(p) }}</strong><span>{{ p.workflow_statistics.failed }} 个失败实例 →</span></button>
      <button v-for="n in problemNodes.slice(0, 2)" :key="n.id" class="attention-item" @click="$emit('resources')"><span class="status warn">{{ nodeIssue(n) }}</span><strong>{{ n.role === 'masters' ? 'Master' : 'Worker' }} · {{ n.host || n.id }}</strong><span>查看节点 →</span></button>
      <p v-if="!attentionProjects.length && !problemNodes.length" class="empty">{{ reliable ? '当前范围暂无已知失败项目或异常节点' : '当前暂无已知异常，请结合采集状态确认数据完整性' }}</p>
    </div><button v-if="attentionProjects.length > 3 || problemNodes.length > 2" class="link-button" @click="$emit('projects')">查看全部项目与异常 →</button>
  </section>
</template>
<script setup>
import { computed } from 'vue'
const props = defineProps({ projects: {type:Array,default:()=>[]}, nodes:{type:Array,default:()=>[]}, pending:Boolean, reliable:Boolean, fresh:Boolean, known:Boolean })
defineEmits(['instances','definitions','projects','resources','alerts'])
const label=p=>p.description?.trim() || p.name || String(p.id)
const attentionProjects=computed(()=>props.projects.filter(p=>p.workflow_statistics?.failed>0).slice().sort((a,b)=>b.workflow_statistics.failed-a.workflow_statistics.failed))
function nodeIssue(n){if(!props.fresh || n.metrics_stale)return '数据待更新';if(!n.online)return '节点离线 / 未知';if([n.cpu_percent,n.host_memory_percent].some(v=>v != null && Number(v)>=85))return '资源使用偏高';return ''}
const problemNodes=computed(()=>props.nodes.filter(n=>nodeIssue(n)))
</script>
<style scoped>
.ds-overview-panel{background:white;border:1px solid #dce4e9;border-radius:5px;padding:18px;margin-bottom:18px}.ds-overview-panel header,.actions{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}.ds-overview-panel h2{font-size:16px;color:#263746;margin:0}.ds-overview-panel p{font-size:12px;color:#687b89;line-height:1.7;margin:5px 0 12px}.attention-panel{border-left:3px solid #dc7b42}.count{font-size:12px;background:#fff0e4;color:#a84e22;border-radius:12px;padding:3px 8px;margin-left:5px}.attention-items{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:0 20px}.attention-item{display:flex;align-items:center;text-align:left;flex-wrap:wrap;gap:10px;padding:12px 0;border:0;border-bottom:1px solid #edf1f4;background:white;font-size:12px;cursor:pointer;color:#334155}.attention-item>span:last-child{margin-left:auto;color:#16738c}.link-button{border:0;background:none;color:#16738c;cursor:pointer;font:inherit;font-size:12px;padding:0}.project-health-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:12px;margin-bottom:14px}.project-health-card{border:1px solid #dce4e9;border-left:3px solid #26899a;background:#fafcfd;border-radius:4px;padding:14px;min-width:0}.project-health-card.has-failure{border-left-color:#c95d4e}.project-title{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.project-title button{text-align:left;font-size:13px;font-weight:600;overflow-wrap:anywhere}.status{font-size:10px;padding:3px 6px;border-radius:3px;white-space:nowrap}.down{background:#fbe9e8;color:#aa3838}.up{background:#e7f4ed;color:#206b46}.unknown{background:#edf0f3;color:#6a7883}.running{background:#e5f1fa;color:#226591}.warn{background:#fff1d9;color:#96600e}.project-counts{display:grid;grid-template-columns:repeat(4,1fr);gap:4px}.project-counts button{border:0;border-top:1px solid #e4ebef;padding:8px 0 0;background:none;text-align:left;cursor:pointer;color:#536c7d}.project-counts button:disabled{cursor:default}.project-counts span{display:block;font-size:10px}.project-counts strong{font-size:18px;color:#263746}.project-counts .failed-count{color:#b74236}.actions input{border:1px solid #d2dde3;border-radius:4px;padding:8px;font-size:12px;max-width:100%}.empty{padding:12px 0}button:focus-visible{outline:2px solid #27879a;outline-offset:3px}@media(max-width:600px){.actions{width:100%}.actions input{flex:1;min-width:0}.project-health-grid{grid-template-columns:1fr}.attention-items{grid-template-columns:1fr}}
</style>
